<script setup lang="ts">
import { computed } from 'vue'
import type { ExpressionContent, FactContent, PreparationContent, PreparationKind, PreparationReference, ProjectContent, TargetContent } from '../../api/preparation'
import { dimensionOptions, expressionOptions, responsibilityLabels } from '../../api/preparation'
import MarkdownPreview from '../MarkdownPreview.vue'
import MaterialExcerptReadout from '../material/MaterialExcerptReadout.vue'
import PreparationCollectionReference from './PreparationCollectionReference.vue'
import TargetRequirementEvidence from './TargetRequirementEvidence.vue'
import TargetPreparationTimeline from './TargetPreparationTimeline.vue'
import TargetLinkedMaterials from './TargetLinkedMaterials.vue'
import RIcon from '../../replica/RIcon.vue'
const props = defineProps<{ kind: PreparationKind; content: PreparationContent; workspace?: boolean; references?: PreparationReference[]; itemId?: string; versionId?: string }>()
const emit = defineEmits<{ open: [reference: PreparationReference] }>()
const target = computed(() => props.content as TargetContent)
const project = computed(() => props.content as ProjectContent)
const fact = computed(() => props.content as FactContent)
const expression = computed(() => props.content as ExpressionContent)
const source = computed(() => (props.content as ProjectContent | FactContent).source)
const linkedReferences = computed(() => (props.references ?? []).filter(reference => props.kind === 'TARGET'
  && target.value.links.some(link => link.kind === reference.kind && link.itemId === reference.itemId && link.versionId === reference.versionId)))
const dimensionName = (value: string) => dimensionOptions.find(option => option.value === value)?.label ?? value
const validUrl = (value: string) => { try { return ['http:', 'https:'].includes(new URL(value).protocol) } catch { return false } }
</script>

<template>
  <article class="prepare-readout" :class="{ 'readout-workspace': workspace, 'readout-target': kind === 'TARGET' }">
    <div class="readout-main">
    <h2 v-if="kind !== 'TARGET'">{{ content.title }}</h2>
    <template v-if="kind === 'TARGET'"><header class="readout-target-heading"><div class="target-title-line"><RIcon name="building" :size="35" /><h2>{{ content.title }}</h2><slot name="target-actions" /></div><p v-if="target.company && !content.title.includes(target.company)" class="muted">{{ target.company }}</p><div class="target-metadata"><span><RIcon name="calendar" :size="23" />{{ target.capturedOn ? `JD ${target.capturedOn.slice(5).replace('-', '.')}` : '未填写资料日期' }}</span><span v-if="target.links.some(link => link.kind === 'PROJECT')"><RIcon name="folder" :size="23" />项目 {{ target.links.filter(link => link.kind === 'PROJECT').length }}</span><span v-if="target.links.some(link => link.kind === 'COLLECTION')"><RIcon name="route" :size="23" />题单／路线 {{ target.links.filter(link => link.kind === 'COLLECTION').length }}</span></div></header>
      <section class="readout-requirement-panel"><h3>要求与考察项</h3><p v-if="!target.requirements.length" class="field-help">该版本没有拆解要求。</p><TargetRequirementEvidence v-else-if="workspace && itemId && versionId" :target-id="itemId" :version-id="versionId" :requirements="target.requirements" /><table v-else class="readout-requirements"><thead><tr><th>要求</th><th>考察项</th><th>优先级</th></tr></thead><tbody><tr v-for="requirement in target.requirements" :key="requirement.id"><td>{{ requirement.text }}</td><td>{{ requirement.dimensions.map(dimensionName).join(' / ') }}</td><td>{{ requirement.priority }}</td></tr></tbody></table></section>
      <TargetLinkedMaterials v-if="workspace && itemId && versionId" :target-id="itemId" :version-id="versionId" :references="linkedReferences" @open="emit('open', $event)" />
      <details class="target-jd" :open="!workspace"><summary>岗位原始 JD</summary><a v-if="validUrl(target.sourceUrl)" class="text-link" :href="target.sourceUrl" target="_blank" rel="noopener noreferrer">查看用户记录的 JD 来源</a><MarkdownPreview :value="target.jd" /><div v-for="link in target.links" :key="link.versionId" class="readout-reference"><button v-if="linkedReferences.find(reference => reference.versionId === link.versionId && reference.itemId === link.itemId)" class="text-link" @click="emit('open', linkedReferences.find(reference => reference.versionId === link.versionId && reference.itemId === link.itemId)!)">{{ linkedReferences.find(reference => reference.versionId === link.versionId && reference.itemId === link.itemId)!.title }}</button><p v-else class="readout-identity">{{ link.kind }} · {{ link.itemId }} · {{ link.versionId }}</p><PreparationCollectionReference v-if="link.kind === 'COLLECTION'" :item-id="link.itemId" :version-id="link.versionId" /></div></details>
    </template>
    <template v-else-if="kind === 'PROJECT'"><MarkdownPreview :value="project.overview" /><h3>技术与适用版本</h3><p class="preserve">{{ project.technology || '未记录' }}</p></template>
    <template v-else-if="kind === 'FACT'"><p class="status-pill">{{ responsibilityLabels[fact.responsibility] }}</p><dl class="fact-fields"><template v-for="field in ([['scenario', '场景'], ['problem', '问题'], ['action', '我的动作'], ['result', '结果与证据'], ['technology', '技术与适用版本']] as const)" :key="field[0]"><dt>{{ field[1] }}</dt><dd class="preserve">{{ fact[field[0]] || '未记录' }}</dd></template></dl></template>
    <template v-else-if="kind === 'EXPRESSION'"><p class="field-help">{{ expressionOptions.find(option => option.value === expression.type)?.label }}</p><MarkdownPreview :value="expression.body" /></template>
    <p v-if="'tags' in content && content.tags.length" class="field-help">标签：{{ content.tags.join(' · ') }}</p>
    </div>
    <aside class="readout-aside">
      <template v-if="kind === 'TARGET'">
        <TargetPreparationTimeline v-if="workspace && itemId && versionId" :target-id="itemId" :version-id="versionId" :captured-on="target.capturedOn" />
        <section class="readout-budget"><h3>{{ workspace ? '本周预算' : '每周预算' }}</h3><div v-if="target.weeklyMinutes !== null" class="target-budget-value"><p><strong>{{ target.weeklyMinutes % 60 === 0 ? target.weeklyMinutes / 60 : target.weeklyMinutes }}</strong> {{ target.weeklyMinutes % 60 === 0 ? '小时' : '分钟' }}</p><RouterLink v-if="workspace" :to="{ name: 'schedule' }"><RIcon name="calendar" :size="20" />调整安排</RouterLink></div><p v-else class="field-help">未填写每周准备预算。</p><p v-if="workspace" class="field-help">每周准备预算；尚无实际用时记录。</p></section>
      </template>
      <template v-if="kind === 'PROJECT' || kind === 'FACT'"><section><h3><RIcon name="file-text" />来源</h3><p>{{ source.title || '用户手工记录，未填写出处标题' }}</p><a v-if="validUrl(source.url)" class="text-link" :href="source.url" target="_blank" rel="noopener noreferrer">{{ source.url }}</a><p class="preserve">{{ source.note || '未填写来源备注' }}</p></section><section v-if="source.excerptIds?.length"><h3>引用的附件原文</h3><MaterialExcerptReadout v-for="id in source.excerptIds" :key="id" :id="id" /></section></template>
      <section v-if="kind === 'EXPRESSION'"><h3><RIcon name="link" />依据事实</h3><div v-for="versionId in expression.factVersionIds" :key="versionId" class="readout-reference"><button v-if="references?.find(reference => reference.versionId === versionId)" class="text-link" @click="emit('open', references!.find(reference => reference.versionId === versionId)!)">{{ references!.find(reference => reference.versionId === versionId)!.title }} · v{{ references!.find(reference => reference.versionId === versionId)!.number }}</button><p v-else class="readout-identity">{{ versionId }}</p></div><p class="field-help">引用确切事实版本；表达与事实分别保存。</p></section>
      <slot name="aside" />
    </aside>
  </article>
</template>

<style scoped>
.prepare-readout { display: grid; gap: 18px; min-width: 0; max-width: 75ch; }
.readout-main { display: grid; align-content: start; gap: 18px; min-width: 0; }.readout-main > :is(h2,p,a) { overflow-wrap: anywhere; }.readout-main > h3 { margin-top: 12px; }.readout-main > .status-pill { justify-self: start; }
.preserve { white-space: pre-wrap; }
.readout-requirement-panel { min-width: 0; }.readout-requirements { width: 100%; border-collapse: collapse; text-align: left; }.readout-requirements th { color: var(--muted); font-weight: 400; white-space: nowrap; }.readout-requirements th,.readout-requirements td { padding: 12px 8px; border-bottom: 1px solid var(--line); }.readout-requirements td:first-child { width: 58%; }.target-jd > summary { cursor: pointer; color: var(--muted); }.target-jd[open] > :not(summary) { margin-top: 18px; }
.fact-fields { display: grid; grid-template-columns: 124px minmax(0,1fr); gap: 27px 22px; margin: 10px 0; }.fact-fields dt { color: var(--muted); }.fact-fields dd { margin: 0; overflow-wrap: anywhere; }
.readout-aside { display: grid; align-content: start; gap: 18px; min-width: 0; }.readout-aside section { display: grid; gap: 18px; min-width: 0; }.readout-aside h3 { display: flex; align-items: center; gap: 12px; margin: 0; }.readout-aside p,.readout-aside a { overflow-wrap: anywhere; }.readout-identity { font: 12px/1.7 Consolas,monospace; overflow-wrap: anywhere; }.readout-reference { padding: 14px 0; border-bottom: 1px solid var(--line); }.readout-reference > button { display: flex; gap: 9px; align-items: center; width: 100%; text-align: left; }.readout-reference > button > svg:last-child { margin-left: auto; }.readout-budget strong { font-size: 38px; font-weight: 500; }
.readout-workspace { grid-template-columns: minmax(0,1fr) 280px; max-width: none; align-items: start; }.readout-workspace .readout-main,.readout-workspace .readout-aside > section { padding: 26px; border: 1px solid var(--line); border-radius: 19px; background: var(--surface); }.readout-workspace .readout-main { min-height: 570px; }.readout-workspace .readout-main > h2 { font-size: 30px; }.readout-workspace .readout-main > .field-help { display: flex; align-items: center; gap: 10px; }.readout-workspace .fact-fields { grid-template-columns: 110px minmax(0,1fr); gap: 28px 24px; }.readout-workspace .readout-aside { font-size: 18px; line-height: 1.7; }
.readout-target.readout-workspace { grid-template-columns: minmax(0,1fr) 328px; gap: 10px; }.readout-target.readout-workspace .readout-main { gap: 10px; padding: 0; border: 0; background: none; min-height: 0; }.readout-target.readout-workspace .readout-target-heading { padding: 23px 22px 17px; }.target-title-line { display: flex; align-items: center; gap: 16px; }.target-title-line > svg { flex: none; color: #83cbb3; }.target-title-line h2 { margin: 0; flex: 1; min-width: 0; font-size: 28px; line-height: 1.5; overflow-wrap: anywhere; }.target-metadata { display: flex; flex-wrap: wrap; gap: 22px; color: var(--muted); margin-top: 24px; font-size: 19px; }.target-metadata span { display: flex; align-items: center; gap: 9px; }.readout-target.readout-workspace :is(.readout-requirement-panel,.target-materials) { padding: 18px 21px; border: 1px solid var(--line); border-radius: 22px; background: linear-gradient(120deg,#25211c90,#18161280 70%); }.readout-requirement-panel h3 { margin: 0 0 8px; }.readout-target.readout-workspace .readout-aside { gap: 10px; }.readout-target.readout-workspace .readout-aside > section { padding: 24px 28px; border-radius: 22px; background: linear-gradient(120deg,#25211c90,#18161280 70%); }.readout-target.readout-workspace .readout-aside > .readout-budget { padding: 19px 22px; }.readout-budget h3 { font-size: 23px; }.target-budget-value { display: flex; align-items: center; gap: 14px; justify-content: space-between; }.target-budget-value p { font-size: 19px; white-space: nowrap; }.target-budget-value a { display: flex; gap: 8px; align-items: center; padding: 10px 12px; border: 1px solid var(--line); border-radius: 22px; background: #ffffff04; font-size: 15px; white-space: nowrap; }.readout-target.readout-workspace .target-jd { margin: 6px 22px; font-size: 14px; }
@media(max-width:1200px) { .readout-workspace { grid-template-columns: minmax(0,1fr); }.readout-workspace .readout-aside { grid-template-columns: repeat(auto-fit,minmax(220px,1fr)); }.fact-fields { grid-template-columns: 105px minmax(0,1fr); } }
@media(max-width:1250px) { .readout-target.readout-workspace { grid-template-columns: minmax(0,1fr); }.readout-target.readout-workspace .readout-aside { grid-template-columns: repeat(auto-fit,minmax(220px,1fr)); } }
@media(max-width:600px) { .fact-fields,.readout-workspace .fact-fields { grid-template-columns: 1fr; gap: 8px; }.fact-fields dd { margin-bottom: 18px; }.readout-workspace .readout-main,.readout-workspace .readout-aside > section { padding: 20px; }.readout-requirements { font-size: 16px; } }
</style>
